import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.3
.target sm_89
.address_size 64

.visible .entry layernorm_kernel(
    .param .u64 param_X,
    .param .u64 param_W,
    .param .u64 param_B,
    .param .u64 param_Y,
    .param .u32 param_N,
    .param .u32 param_M,
    .param .f32 param_eps
)
{
    .reg .pred %p<20>;
    .reg .f32 %f<60>;
    .reg .b32 %r<80>;
    .reg .b64 %rd<25>;

    .shared .align 4 .f32 warpSums[32];
    .shared .align 4 .f32 warpSumSqs[32];
    .shared .align 4 .f32 mean_s;
    .shared .align 4 .f32 inv_std_s;

    ld.param.u64 %rd1, [param_X];
    ld.param.u64 %rd2, [param_W];
    ld.param.u64 %rd3, [param_B];
    ld.param.u64 %rd4, [param_Y];
    ld.param.u32 %r1, [param_M];
    ld.param.f32 %f1, [param_eps];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %tid.x;
    mov.u32 %r4, %ntid.x;

    mul.lo.s32 %r5, %r2, %r1;

    // vector count and remainder for M (M elements per row)
    shr.u32 %r6, %r1, 2;
    and.b32 %r7, %r1, 3;

    // row base addresses (byte)
    mul.wide.s32 %rd5, %r5, 4;
    add.s64 %rd6, %rd1, %rd5;   // X row base
    add.s64 %rd7, %rd4, %rd5;   // Y row base

    mov.f32 %f2, 0f00000000;
    mov.f32 %f3, 0f00000000;

    mov.u32 %r8, %r3;

LOOP1_VEC_COND:
    setp.ge.s32 %p1, %r8, %r6;
    @%p1 bra LOOP1_VEC_DONE;

    mul.wide.s32 %rd8, %r8, 16;
    add.s64 %rd9, %rd6, %rd8;
    ld.global.v4.f32 {%f4, %f5, %f6, %f7}, [%rd9];

    add.f32 %f2, %f2, %f4;
    add.f32 %f2, %f2, %f5;
    add.f32 %f2, %f2, %f6;
    add.f32 %f2, %f2, %f7;

    fma.rn.f32 %f3, %f4, %f4, %f3;
    fma.rn.f32 %f3, %f5, %f5, %f3;
    fma.rn.f32 %f3, %f6, %f6, %f3;
    fma.rn.f32 %f3, %f7, %f7, %f3;

    add.s32 %r8, %r8, %r4;
    bra.uni LOOP1_VEC_COND;

LOOP1_VEC_DONE:

    setp.ge.s32 %p2, %r3, %r7;
