    shl.b32 %r9, %r6, 2;
    add.s32 %r9, %r9, %r3;

    mul.wide.s32 %rd10, %r9, 4;
    add.s64 %rd11, %rd6, %rd10;
    ld.global.f32 %f8, [%rd11];

    add.f32 %f2, %f2, %f8;
    fma.rn.f32 %f3, %f8, %f8, %f3;

LOOP1_TAIL_DONE:

    mov.u32 %r10, 0xffffffff;
    mov.u32 %r11, 31;

    mov.u32 %r12, 16;
    mov.b32 %r13, %f2;
    shfl.sync.down.b32 %r14|%p2, %r13, %r12, %r11, %r10;
    mov.b32 %f5, %r14;
    add.f32 %f2, %f2, %f5;

    mov.b32 %r15, %f3;
    shfl.sync.down.b32 %r16|%p3, %r15, %r12, %r11, %r10;
    mov.b32 %f6, %r16;
    add.f32 %f3, %f3, %f6;

    mov.u32 %r12, 8;
    mov.b32 %r13, %f2;
    shfl.sync.down.b32 %r14|%p2, %r13, %r12, %r11, %r10;
    mov.b32 %f5, %r14;
    add.f32 %f2, %f2, %f5;

    mov.b32 %r15, %f3;
    shfl.sync.down.b32 %r16|%p3, %r15, %r12, %r11, %r10;
    mov.b32 %f6, %r16;
    add.f32 %f3, %f3, %f6;

    mov.u32 %r12, 4;
    mov.b32 %r13, %f2;
    shfl.sync.down.b32 %r14|%p2, %r13, %r12, %r11, %r10;
    mov.b32 %f5, %r14;
    add.f32 %f2, %f2, %f5;

    mov.b32 %r15, %f3;
    shfl.sync.down.b32 %r16|%p3, %r15, %r12, %r11, %r10;
    mov.b32 %f6, %r16;
    add.f32 %f3, %f3, %f6;

    mov.u32 %r12, 2;
    mov.b32 %r13, %f2;
    shfl.sync.down.b32 %r14|%p2, %r13, %r12, %r11, %r10;
    mov.b32 %f5, %r14;
    add.f32 %f2, %f2, %f5;

    mov.b32 %r15, %f3;
    shfl.sync.down.b32 %r16|%p3, %r15, %r12, %r11, %r10;
    mov.b32 %f6, %r16;
    add.f32 %f3, %f3, %f6;

    mov.u32 %r12, 1;
    mov.b32 %r13, %f2;
    shfl.sync.down.b32 %r14|%p2, %r13, %r12, %r11, %r10;
    mov.b32 %f5, %r14;
    add.f32 %f2, %f2, %f5;

    mov.b32 %r15, %f3;
    shfl.sync.down.b32 %r16|%p3, %r15, %r12, %r11, %r10;
    mov.b32 %f6, %r16;
    add.f32 %f3, %f3, %f6;

    and.b32 %r20, %r3, 31;
    shr.u32 %r21, %r3, 5;

    setp.ne.s32 %p4, %r20, 0;
    @%p4 bra STORE_DONE;

    mul.lo.s32 %r22, %r21, 4;
    mov.u32 %r23, warpSums;
    add.s32 %r24, %r23, %r22;
    st.shared.f32 [%r24], %f2;

    mov.u32 %r25, warpSumSqs;
    add.s32 %r26, %r25, %r22;
    st.shared.f32 [%r26], %f3;

STORE_DONE:
    bar.sync 0;

    setp.ne.s32 %p5, %r3, 0;
    @%p5 bra FINAL_DONE;

    add.s32 %r30, %r4, 31;
    shr.u32 %r31, %r30, 5;

    mov.f32 %f10, 0f00000000;
    mov.f32 %f11, 0f00000000;
    mov.u32 %r32, 0;

COMBINE_COND:
    setp.ge.s32 %p6, %r32, %r31;
    @%p6 bra COMBINE_DONE;

    mul.lo.s32 %r33, %r32, 4;
    mov.u32 %r34, warpSums;
    add.s32 %r35, %r34, %r33;
    ld.shared.f32 %f12, [%r35];
    add.f32 %f10, %f10, %f12;

    mov.u32 %r36, warpSumSqs;
    add.s32 %r37, %r36, %r33;
    ld.shared.f32 %f13, [%r37];
    add.f32 %f11, %f11, %f13;

    add.s32 %r32, %r32, 1;
    bra.uni COMBINE_COND;

