    div.rn.f32 %f16, %f11, %f14;
    mul.f32 %f17, %f15, %f15;
    sub.f32 %f18, %f16, %f17;
    setp.lt.f32 %p7, %f18, 0f00000000;
    selp.f32 %f19, 0f00000000, %f18, %p7;
    add.f32 %f20, %f19, %f1;
    rsqrt.approx.f32 %f21, %f20;

    st.shared.f32 [mean_s], %f15;
    st.shared.f32 [inv_std_s], %f21;

FINAL_DONE:
    bar.sync 0;

    ld.shared.f32 %f22, [mean_s];
    ld.shared.f32 %f23, [inv_std_s];

    mov.u32 %r8, %r3;

LOOP2_VEC_COND:
    setp.ge.s32 %p8, %r8, %r6;
    @%p8 bra LOOP2_VEC_DONE;

