    add.s64 %rd13, %rd6, %rd12;
    ld.global.v4.f32 {%f24, %f25, %f26, %f27}, [%rd13];

    add.s64 %rd14, %rd2, %rd12;
    ld.global.v4.f32 {%f30, %f31, %f32, %f33}, [%rd14];

    add.s64 %rd15, %rd3, %rd12;
    ld.global.v4.f32 {%f34, %f35, %f36, %f37}, [%rd15];

