    fn = module.function("layernorm_kernel")
    assert fn is not None, "layernorm_kernel entry not found in PTX module"
    return fn


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a single fused hand-authored PTX kernel,
    launched via cutegen.ptx_runtime.PtxModule.

    This version vectorizes the global-memory traffic (loads for the
    reduction pass and loads/stores for the normalization pass) using
    ld.global.v4.f32 / st.global.v4.f32 wherever the per-row element
    count allows 4-wide grouping, falling back to scalar accesses for
    any trailing remainder elements. This improves memory throughput
    without changing numerical behavior.
    """

    def __init__(self, normalized_shape):
        super(ModelNew, self).__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))

        self._module = _get_module()
        self._kernel = self._module.function("layernorm_kernel")

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"

        x_c = x.contiguous().to(dtype=torch.float32)
        w_c = self.weight.to(device=x_c.device, dtype=torch.float32).contiguous()
        b_c = self.bias.to(device=x_c.device, dtype=torch.float32).contiguous()

        N = x_c.size(0)
        M = x_c.numel() // N

        assert w_c.numel() == M, "weight numel must match normalized shape size"
        assert b_c.numel() == M, "bias numel must match normalized shape size"

        y = torch.empty_like(x_c)

        threads = 1024
        grid = (int(N), 1, 1)
        block = (threads, 1, 1)

        stream = torch.cuda.current_stream(device=x_c.device).cuda_stream

        self._kernel.launch(
            grid=grid,
            block=block,
            shared_mem_bytes=0,
            stream=stream,
            args=[
                u64(x_c.data_ptr()),
                u64(w_c.data_ptr()),
                u64(b_c.data_ptr()),
                u64(y.data_ptr()),
                i32(int(N)),
                i32(int(M)),
                f32(float(self.eps)),
            ],
        )

        return y

